			/**
			 * 타이틀 클릭시 컨텐츠 접고 펼치기 기능
			 */
			function grpTitleClick(e) {
			    var vcTitleCtrl = e.control;
			    
			    contentsExpand(vcTitleCtrl);
			}

			/**
			 * 타이틀 클릭시 컨텐츠 visible 처리(접고 펼치기 기능)
			 * @param {#uicontrol} pcGrpTitle 타이틀 그룹
			 */
			function contentsExpand(pcGrpTitle) {
			    /**@type cpr.controls.Container */
			    var vcTitleCtrl = pcGrpTitle;
			    var vcParents = vcTitleCtrl.getParent();
			    var vcGrpConts;
			    
			    // 상세 컨텐츠 반환 부모그룹에는 무조건 타이틀과 컨텐츠가 한 세트로 구성됨
			    var vcGrpConts = vcParents.getChildren().filter(function(ctrl) {
			        if (ctrl.id != vcTitleCtrl.id) {
			            return vcGrpConts = ctrl;
			        }
			    });
			    
			    if (vcGrpConts[0].visible) {
			        vcGrpConts[0].visible = false;
			    } else {
			        vcGrpConts[0].visible = true;
			    }
			}

			/**
			 * 답글등록시 입력 폼을 그립니다.
			 * @param {Number} pnRowIdx
			 */
			function drawInsertReplyForm(pnRowIdx) {
			    
			    var voRow = app.lookup("dsBoardDtlReplyList").getRow(pnRowIdx);
			    var vcGrpInsReplyBody = new cpr.controls.Container("grpInsReplyBody");
			    
			    // Layout
			    var voInsReplyLot = new cpr.controls.layouts.VerticalLayout();
			    vcGrpInsReplyBody.userData("rowIdx", pnRowIdx);
			    vcGrpInsReplyBody.setLayout(voInsReplyLot);
			    (function(container) {
			        var userDefinedControl_2 = new udc.com.comFormTitle("comReplyTitle");
			        userDefinedControl_2.title = "답글 작성";
			        container.addChild(userDefinedControl_2, {
			            "autoSize": "none",
			            "width": "1260px",
			            "height": "25px"
			        });
			        var vcBrdReplyForm = createBoardReplyForm(voRow, true);
			        container.addChild(vcBrdReplyForm, {
			            "autoSize": "height",
			            "width": "1260px",
			            "height": "584px"
			        });
			        
			    })(vcGrpInsReplyBody);
			    app.lookup("grpData").addChild(vcGrpInsReplyBody, {
			        "autoSize": "height",
			        "width": "1260px",
			        "height": "583px"
			    });
			}

			/**
			 * 게시판 상세 컨텐츠 컨트롤 생성
			 * @param {cpr.controls.Container} pcGrpCtrl 초기화 그룹 ID
			 * @param {Object} poParams 추가 컬럼 param
			 * @param {Number} pnReteCd 답글 고유 번호
			 * @return {Object} 생성된 컨트롤 및 constraint
			 */
			function createBoardCtrl(pcGrpCtrl, poParams, pnReteCd) {
			    
			    var voDsDtlColDataList = app.lookup("dsBoardDtlColDataList");
			    
			    var vcGrpForm = pcGrpCtrl;
			    var voConst = JSON.parse(poParams["COL_PLACEM_INFO_CN"]);
			    
			    var vnRowIdx = voConst["rowIndex"];
			    var vnColIdx = voConst["colIndex"];
			    var vsColId = poParams["NTABRD_COL_ESNTAL_ID"];
			    var vsBrdTmptSeCd = poParams["NTABRD_TMPT_SE_CD"]; // 게시글 상세입력, 답글 구분코드
			    var voDmColData;
			    var vbIsTarget = true;
			    
			    /* 데이터 맵 바인딩 컬럼 추가*/
			    if (vsBrdTmptSeCd == "1") { // 상세
			        voDmColData = app.lookup("dmColData");
			        
			        // 기본값 존재시 default value 적용
			        if (!ValueUtil.isNull(poParams["COL_BASS_VALUE"])) {
			            voDmColData.addColumn(new cpr.data.header.DataHeader(vsColId, "string", poParams["COL_BASS_VALUE"]));
			        } else {
			            voDmColData.addColumn(new cpr.data.header.DataHeader(vsColId, "string"));
			        }
			    } else { // 답글
			        if (pnReteCd == mnSeltBrdReplySeq) { // 선택된 답글
			            voDmColData = app.lookup("dmReplyColData");
			            voDmColData.setValue("RETE_ESNTAL_NO", pnReteCd);
			            voDmColData.addColumn(new cpr.data.header.DataHeader(vsColId, "string"));
			        } else if (ValueUtil.isNull(pnReteCd)) { // 신규 쓰기인경우                 
			            voDmColData = app.lookup("dmInsertReplyColData");
			            voDmColData.setValue("RETE_ESNTAL_NO", "");
			            
			            // 기본값 존재시 default value 적용
			            if (!ValueUtil.isNull(poParams["COL_BASS_VALUE"])) {
			                voDmColData.addColumn(new cpr.data.header.DataHeader(vsColId, "string", poParams["COL_BASS_VALUE"]));
			            } else {
			                voDmColData.addColumn(new cpr.data.header.DataHeader(vsColId, "string"));
			            }
			        } else {
			            vbIsTarget = false;
			        }
			    }
			    
			    /* Label 컨트롤 생성 */
			    var voLabelConst = {
			        "colIndex": Number(vnColIdx) - 1,
			        "rowIndex": vnRowIdx
			    }
			    
			    var vcLabelCtrl = new cpr.controls.Output("_optLabel" + vnRowIdx + vnColIdx);
			    vcLabelCtrl.value = poParams["NTABRD_COL_NM"];
			    
			    /* Type 컨트롤 생성 */
			    var vcCtrl = null;
			    switch (poParams["NTABRD_COL_TYPE_NM"]) {
			        case "COMBO":
			            vcCtrl = new cpr.controls.ComboBox();
			            break;
			        case "LINKCOMBO":
			            vcCtrl = new cpr.controls.LinkedComboBox();
			            break;
			        case "CHECK":
			            vcCtrl = new cpr.controls.CheckBoxGroup();
			            break;
			        case "RADIO":
			            vcCtrl = new cpr.controls.RadioButton();
			            break;
			        case "DATE":
			            vcCtrl = new cpr.controls.DateInput();
			            break;
			        default:
			            vcCtrl = new cpr.controls.InputBox();
			            break;
			    }
			    vcCtrl.fieldLabel = poParams["NTABRD_COL_NM"];
			    vcCtrl.lengthUnit = "utf8";
			    vcCtrl.maxLength = 2000;
			    if (vbIsTarget) { // 기본상세, 타겟 답글이 있는경우
			        vcCtrl.bind("value").toDataMap(voDmColData, vsColId);
			    } else {
			        var voRow = voDsDtlColDataList.findFirstRow("RETE_ESNTAL_NO =='" + pnReteCd + "' && NTABRD_COL_ESNTAL_ID =='" + vsColId + "'");
			        if (voRow) {
			            vcCtrl.bind("value").toDataSet(voDsDtlColDataList, "NTABRD_COL_CN", voRow.getIndex());
			        }
			    }
			    
			    // 공통코드 존재시 바인딩
			    if (!ValueUtil.isNull(poParams["CMMNS_CD_ID"])) {
			        var dsCmnNm = "ds" + poParams["NTABRD_COL_ESNTAL_ID"] + poParams["CMMNS_CD_ID"];
			        
			        (function(vcCtrl) {
			            vcCtrl.setItemSet(moDsCmnList[dsCmnNm], {
			                "label": "CMMNS_CD_VALUE_NM",
			                "value": "CMMNS_CD_VALUE"
			            });
			        })(vcCtrl);
			    }
			    
			    // 라벨 필수여부 체크
			    if (poParams["ESNTL_YN"] == "Y") {
			        vcLabelCtrl.style.setClasses(["label", "require"]);
			        vcCtrl.userAttr("required", "Y");
			    } else {
			        vcLabelCtrl.style.setClasses(["label"]);
			    }
			    
			    /* 컨트롤 삽입 */
			    vcGrpForm.addChild(vcLabelCtrl, voLabelConst);
			    vcGrpForm.addChild(vcCtrl, voConst);
			    vcGrpForm.redraw();
			    
			}

			/**
			 * 변경사항을 체크합니다.
			 * @return {Boolean} 변경유무
			 */
			function _isModified() {
			    
			    var voDsBrdDtlList, vcHtmlEdit, vcFile, vsBeforeCont;
			    var voDsBrdDtlColDataList = app.lookup("dsBoardDtlColDataList");
			    var vbIsModified = false;
			    
			    if (mnSeltBrdReplySeq == "0") {
			        voDsBrdDtlList = app.lookup("dsBoardDtlList");
			        vcHtmlEdit = app.lookup("cmnHtmlEditor");
			        vcFile = app.lookup("cmnMultifileupload");
			        vsBeforeCont = voDsBrdDtlList.getValue(0, "BBSCTT_CN");
			        
			    } else {
			        var vcBody = getTargetCtrl("body");
			        voDsBrdDtlList = app.lookup("dsBoardDtlReplyList");
			        vcHtmlEdit = getTargetCtrl("editer");
			        vcFile = getTargetCtrl("file");
			        
			        var vnRowIdx = voDsBrdDtlList.findFirstRow("RETE_ESNTAL_NO == '" + mnSeltBrdReplySeq + "'").getIndex();
			        vsBeforeCont = voDsBrdDtlList.getValue(vnRowIdx, "RETE_CN");
			    }
			    
			    var vsContent = vcHtmlEdit.getValue();
			    
			    if (voDsBrdDtlList.isModified()) {
			        vbIsModified = true;
			    } else if (voDsBrdDtlColDataList.isModified()) {
			        vbIsModified = true;
			    } else if (vsContent != vsBeforeCont) {
			        vbIsModified = true;
			    } else if (vcFile.isFileModified()) {
			        vbIsModified = true;
			    }
			    
			    return vbIsModified;
			}

