			/*
			 * 루트 컨테이너에서 property-change 이벤트 발생 시 호출.
			 * 앱의 속성이 변경될 때 발생하는 이벤트 입니다.
			 */
			function onBodyPropertyChange( /* cpr.events.CPropertyChangeEvent */ e) {
			    
			    if (e.property == "initValue") {
			        
			        // 게시판 기본 정보 구성
			        var voDmBrdInfo = app.lookup("dmBoardInfo");
			        e.newValue["dmBoardInfo"].copyToDataMap(voDmBrdInfo);
			        
			        msBrdId = voDmBrdInfo.getValue("NTABRD_ESNTAL_NO");
			        util.DataMap.setValue(app, "dmParam", "NTABRD_ESNTAL_NO", msBrdId);
			        
			        // 화면에 동적 공통코드 존재시 구성합니다.      
			        moDsCmnList = e.newValue["dsCmnList"];
			        
			        // 게시판 정보 데이터로 기본 게시글 상세화면을 그립니다.
			        if (!ValueUtil.isNull(e.newValue["dsColList"])) {
			            
			            e.newValue["dsColList"].copyToDataSet(app.lookup("dsBoardColList"));
			            drawBoardDtlForm();
			        }
			    }
			}

