			/*
			 * "저장" 버튼(btnUpdAdd4)에서 click 이벤트 발생 시 호출.
			 * 사용자가 컨트롤을 클릭할 때 발생하는 이벤트.
			 */
			function onBtnSaveClick( /* cpr.events.CMouseEvent */ e) {
			    
			    var vcFld;
			    
			    if (mnSeltBrdReplySeq == 0) { // 기본 게시글
			        
			        vcFld = app.lookup("cmnMultifileupload");
			        
			        var vcHtmlEdit = app.lookup("cmnHtmlEditor");
			        var vsContent = vcHtmlEdit.getValue();
			        
			        util.DataSet.setValue(app, "dsBoardDtlList", 0, "BBSCTT_CN", vsContent);
			        
			        if (vsContent.length > 20008) {
			            util.Msg.alert(app, "내용은 최대 20,000자 까지 입력 가능합니다.\n (현재 글자수: " + (vsContent.length - 8) + "자)");
			            return false;
			        }
			        
			        // 변경사항 체크
			        if (!_isModified()) {
			            util.Msg.alert(app, "INF-M006");
			            return false;
			        }
			        
			        // 유효성 체크
			        if (!util.validate(app, "grpBoardDtl")) return false;
			        
			    } else { // 답글
			        var vcBody = getTargetCtrl("body");
			        vcFld = getTargetCtrl("file");
			        var vcHtmlEdit = getTargetCtrl("editer");
			        var vsContent = vcHtmlEdit.getValue();
			        
			        var vnSeleIdx = app.lookup("dsBoardDtlReplyList").findFirstRow("RETE_ESNTAL_NO =='" + mnSeltBrdReplySeq + "'").getIndex();
			        util.DataSet.setValue(app, "dsBoardDtlReplyList", vnSeleIdx, "RETE_CN", vsContent);
			        
			        if (vsContent.length > 20008) {
			            util.Msg.alert(app, "내용은 최대 20,000자 까지 입력 가능합니다.\n (현재 글자수: " + (vsContent.length - 8) + "자)");
			            return false;
			        }
			        
			        // 변경사항 체크
			        if (!_isModified()) {
			            util.Msg.alert(app, "INF-M006");
			            return false;
			        }
			        
			        // 유효성 체크
			        if (!util.validate(app, vcBody.id)) return false;
			    }
			    
			    vcFld.send(doSave);
			}

