			function onBtnReplyClick(e) {
			    var btnReply = e.control;
			    var voDsBrdDtlReplyList = app.lookup("dsBoardDtlReplyList");
			    
			    // 신규행 추가
			    var voRow = voDsBrdDtlReplyList.addRowData({
			        NTABRD_ESNTAL_NO: msBrdId,
			        BBSCTT_ESNTAL_NO: mnBrdSeq,
			        RETE_WRTR_ID: util.DataMap.getValue(app, "dmUserInfo", "USER_ID"),
			        RETE_WRTR_NM: util.DataMap.getValue(app, "dmUserInfo", "USER_NM"),
			        RDCNT_NOCS: "0",
			        FRST_REG_DT: moment().format("YYYYMMDDHHmmss")
			    });
			    
			    var vnRowIdx = voRow.getIndex();
			    
			    /* 답글쓰기 그리기 */
			    drawInsertReplyForm(vnRowIdx);
			    
			    /* 답글 쓰기시 버튼 동작 */
			    util.Control.setVisible(app, false, ["btnRestore", "btnSave", "btnDelete", "btnUpdate", "btnReply"]);
			    util.Control.setVisible(app, true, ["btnReplySave", "btnReplyRestore"]);
			    
			    cpr.core.DeferredUpdateManager.INSTANCE.asyncExec(function() {
			        // 답글쓰기가 생성되는 스크롤 최하단으로 이동
			        var vcContainer = app.getContainer();
			        var vnContPaneHeight = vcContainer.getContentPaneRect().height;
			        var vnActaulHeihgt = vcContainer.getActualRect().height;
			        var vnViewTop = vnContPaneHeight - vnActaulHeihgt;
			        
			        vcContainer.scrollTo(0, vnViewTop);
			    });
			}

