			/*
			 * 체크 박스에서 before-value-change 이벤트 발생 시 호출.
			 * CheckBox의 value를 변경하여 변경된 값이 저장되기 전에 발생하는 이벤트. 다음 이벤트로 value-change가 발생합니다.
			 */
			function onCbxNctYnBeforeValueChange(e) {
			    var cbxNctYn = e.control;
			    var vcCbxRlsYn = app.lookup("cbxRlsYn");
			    
			    if (vcCbxRlsYn.value == "N") {
			        util.Msg.alert(app, "비밀글은 중요공지로 설정 할 수 없습니다.");
			        e.preventDefault();
			    }
			}

			/*
			 * 체크 박스에서 before-value-change 이벤트 발생 시 호출.
			 * CheckBox의 value를 변경하여 변경된 값이 저장되기 전에 발생하는 이벤트. 다음 이벤트로 value-change가 발생합니다.
			 */
