			/*
			 * "답글저장" 버튼(btnReplySave)에서 click 이벤트 발생 시 호출.
			 * 사용자가 컨트롤을 클릭할 때 발생하는 이벤트.
			 */
			function onBtnReplySaveClick(e) {
			    var btnReplySave = e.control;
			    
			    // 답글쓰기시 생성한 body 아이디로 가져와 타겟을 설정합니다.
			    /** @type cpr.controls.Container */
			    var vcInsReplyBody = app.lookup("grpData").getChild("grpInsReplyBody");
			    var vnTargetRowIdx = vcInsReplyBody.userData("rowIdx");
			    var vcFld = null;
			    var vcEditor = null;
			    
			    vcInsReplyBody.getAllRecursiveChildren().forEach(function(ctrl) {
			        if (ctrl.type == "udc.cmn.cmnMultiFileUpload") {
			            vcFld = ctrl;
			        } else if (ctrl.type == "udc.cmn.cmnHtmlEditor") {
			            vcEditor = ctrl;
			        }
			    });
			    
			    // 답글 쓰기시 변경사항 유무는 판단할 필요가 없으므로 유효성 체크만 진행함    
			    if (!util.validate(app, "grpInsReplyBody")) return false;
			    
			    var vsInsContent = vcEditor.getValue();
			    
			    if (vsInsContent.length > 20008) {
			        util.Msg.alert(app, "INF-M000", "내용은 최대 20,000자 까지 입력 가능합니다.");
			        return false;
			    }
			    util.DataSet.setValue(app, "dsBoardDtlReplyList", vnTargetRowIdx, "RETE_CN", vsInsContent);
			    
			    //TODO 변경된 파일처리 구조 개발후 적용 파일 및 데이터 저장
			    vcFld.send(doSave);
			    
			}

